<?php if(!defined('ABSPATH'))exit;global $wpdb;$a=ICD_Visitas_Database::table('agendas');$v=ICD_Visitas_Database::table('vinculos');$e=ICD_Visitas_Database::table('escolas');$m=ICD_Visitas_Database::table('mediadores');$vincs=$wpdb->get_results("SELECT v.id,e.nome escola,m.nome mediador FROM $v v JOIN $e e ON e.id=v.escola_id JOIN $m m ON m.id=v.mediador_id WHERE v.ativo=1 ORDER BY e.nome,m.nome");$rows=$wpdb->get_results("SELECT a.*,e.nome escola,m.nome mediador FROM $a a JOIN $v v ON v.id=a.vinculo_id JOIN $e e ON e.id=v.escola_id JOIN $m m ON m.id=v.mediador_id WHERE a.ativo=1 ORDER BY a.dia_semana,e.nome,a.turno");?>
<div class="wrap icd-admin"><h1>Agenda recorrente</h1><form class="icd-form-row" method="post" action="<?php echo esc_url(ICD_Visitas_Helpers::action_url());?>"><?php wp_nonce_field('icd_save_agenda');?><input type="hidden" name="action" value="icd_save_agenda"><label>Vínculo<select required name="vinculo_id"><option value="">Selecione</option><?php foreach($vincs as $x)echo '<option value="'.$x->id.'">'.esc_html($x->escola.' — '.$x->mediador).'</option>';?></select></label><label>Dia<select name="dia_semana"><?php for($d=1;$d<=7;$d++)echo '<option value="'.$d.'">'.esc_html(ICD_Visitas_Helpers::dia_label($d)).'</option>';?></select></label><label>Turno<select name="turno"><option value="manha">Manhã</option><option value="tarde">Tarde</option><option value="noite">Noite</option><option value="integral">Integral</option></select></label><label>Início<input type="time" name="hora_inicio"></label><label>Fim<input type="time" name="hora_fim"></label><button class="button button-primary">Adicionar</button></form><table class="widefat striped"><thead><tr><th>Dia</th><th>Escola</th><th>Mediador</th><th>Turno</th><th>Horário</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php echo esc_html(ICD_Visitas_Helpers::dia_label($r->dia_semana));?></td><td><?php echo esc_html($r->escola);?></td><td><?php echo esc_html($r->mediador);?></td><td><?php echo esc_html(ICD_Visitas_Helpers::turno_label($r->turno));?></td><td><?php echo esc_html(trim(($r->hora_inicio?substr($r->hora_inicio,0,5):'').' '.($r->hora_fim?'– '.substr($r->hora_fim,0,5):'')));?></td></tr><?php endforeach;?></tbody></table></div>
